  alternatives={
    {from=1,note={de="Habt ihr genug Leichtes Leder, fertigt ihr von Anfang an 60 Leichte Rüstungssets statt erst Leder zu gerben.",en="If you have enough light leather, make 60 light armor kits from the start instead of tanning first."},steps={{crafts=60,from=1,mats={{2318,1}},rank="apprentice",res={de="Verbrauchbares Rüstungsset, das sich auf ein Rüstungsteil auftragen lässt; der Tooltip nennt die Bedingungen.",en="Consumable armor kit applied to a piece of armor; the tooltip lists the requirements."},spell=2152,src="trainer",to=30}},title={de="Gleich Rüstungssets herstellen",en="Make armor kits right away"},to=30},
